CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text UNIQUE NOT NULL,password_hash text NOT NULL);
CREATE TABLE sessions(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE settings(id int PRIMARY KEY DEFAULT 1 CHECK(id=1),value jsonb NOT NULL DEFAULT '{}');
CREATE TABLE agents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,role text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',instructions text NOT NULL DEFAULT '',color text NOT NULL,shape text NOT NULL,model text,pinned boolean NOT NULL DEFAULT false,section text NOT NULL DEFAULT 'Equipe',memory text NOT NULL DEFAULT '',tools jsonb NOT NULL DEFAULT '[]',skills jsonb NOT NULL DEFAULT '[]',archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agent_id uuid NOT NULL REFERENCES agents ON DELETE CASCADE,title text NOT NULL DEFAULT 'Nova conversa',summary text NOT NULL DEFAULT '',summary_through timestamptz,seen_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE,role text NOT NULL,content text NOT NULL,files jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agent_id uuid NOT NULL REFERENCES agents ON DELETE CASCADE,conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE,parent_id uuid REFERENCES runs ON DELETE SET NULL,state text NOT NULL DEFAULT 'queued',model text NOT NULL,config text NOT NULL,context jsonb NOT NULL DEFAULT '[]',steps int NOT NULL DEFAULT 0,depth int NOT NULL DEFAULT 0,error text,output text,usage jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tool_calls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE,call_id text NOT NULL,tool text NOT NULL,args jsonb NOT NULL,fingerprint text NOT NULL,status text NOT NULL DEFAULT 'pending',external_write boolean NOT NULL DEFAULT false,result text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,call_id));
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),call_id uuid UNIQUE NOT NULL REFERENCES tool_calls ON DELETE CASCADE,fingerprint text NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE skills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,url text NOT NULL,auth text,tools jsonb NOT NULL DEFAULT '[]',read_tools jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'disconnected',oauth text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agent_id uuid REFERENCES agents ON DELETE SET NULL,name text NOT NULL,mime text NOT NULL,size bigint NOT NULL,storage_name text NOT NULL,extracted text NOT NULL DEFAULT '',warning text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE routines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agent_id uuid NOT NULL REFERENCES agents ON DELETE CASCADE,name text NOT NULL,prompt text NOT NULL,kind text NOT NULL,schedule text NOT NULL,timezone text NOT NULL,enabled boolean NOT NULL DEFAULT false,next_at timestamptz,last_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE routine_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),routine_id uuid NOT NULL REFERENCES routines ON DELETE CASCADE,run_id uuid REFERENCES runs ON DELETE SET NULL,status text NOT NULL,scheduled_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(routine_id,scheduled_at));
CREATE TABLE model_capabilities(id text PRIMARY KEY,tools boolean NOT NULL DEFAULT false,vision boolean NOT NULL DEFAULT false,verified_at timestamptz);
CREATE TABLE events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_created ON events(created_at);
CREATE INDEX messages_conversation ON messages(conversation_id,created_at);
CREATE INDEX runs_agent ON runs(agent_id,state);
CREATE INDEX messages_search ON messages USING gin(to_tsvector('portuguese',content));
